    th = _threads([44.0, 40.0], "final_offer", [38.0])
    th["sup:A"][-1]["term_sheets"][0]["terms"]["payment_days"] = 14
    msg = BoulwareAgent().decide(case, th)["message"]
    assert msg["term_sheets"][0]["terms"]["unit_price"] == 40.0 and msg["term_sheets"][0]["terms"]["payment_days"] != 14


